using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Agents.AI;

// Configuration
var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

// DI setup
var services = new ServiceCollection();
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();

// Tools
var researchTools = new ResearchTools();
var tools = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ],
};

// Create the agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research agent that searches the web and takes notes to produce summaries.",
    Instructions = """
        You are a research agent. When given a topic:
        1. Use the SearchWeb tool to find relevant information (perform 2-3 searches with different queries).
        2. Use TakeNote to record key findings as you discover them.
        3. Use GetNotes to review all your collected notes.
        4. Provide a comprehensive summary of your research findings.
        Always cite the sources from your search results.
        """,
};

// Run the agent
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing 2026";
Console.WriteLine($"🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a detailed summary: {topic}"),
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = tools,
};

await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n📝 Notes collected during research:");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"  • {note}");
}

// Tool implementations
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public IReadOnlyList<string> Notes => _notes;

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        // Use a public search API (DuckDuckGo Instant Answer API)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await _httpClient.GetStringAsync(url);
            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText} (Source: {abstractUrl})");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) &&
                        topic.TryGetProperty("FirstURL", out var firstUrl))
                    {
                        results.Add($"{text.GetString()} (Source: {firstUrl.GetString()})");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Records a research note for later reference. Use this to save important findings.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📌 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

